    'fu.td.bankscond':      'Practically nothing',
    'fu.p4':                '<strong>Questrade</strong> is great for investing — but not for your emergency fund. Its cash account earns practically nothing. For accessible money, EQ Bank and Wealthsimple Cash are far superior.',
    'fu.h2.steps':          'My 4-step plan',
    'fu.step1.title':       'Calculate your target emergency fund',
    'fu.step1.desc':        'Monthly expenses × 6 months = your target. For entrepreneurs, aim for 9-12 months.',
    'fu.step2.title':       'Open a high-interest savings account',
